<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- elite four card shell from arenaSnapshot */
  import { arena } from '../../stores/arena.svelte.ts';
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { useGameLanguageTick } from '../../lib/useGameLanguageTick.svelte.ts';
  import ArenaEliteTrainerDex from './ArenaEliteTrainerDex.svelte';

  const { trackGameLanguage } = useGameLanguageTick();

  let snap = $derived(arena.snapshot);

  const teamLabel = $derived.by(() => {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm?.t) return 'Équipe';
    const out = gm.t('subway.teamLabel');
    return out && out !== 'subway.teamLabel' ? out : 'Équipe';
  });
</script>

<div id="eliteFourContainer">
  <!-- svelte-ignore a11y_no_static_element_interactions -->
  {@html snap.eliteFourHtml}
  <ArenaEliteTrainerDex trainers={snap.eliteFourTrainers} {teamLabel} />
</div>
