<script lang="ts">
  import type { EliteFourTrainerPreviewSnapshot } from '../../bus/snapshots.js';

  let {
    trainers = [] as EliteFourTrainerPreviewSnapshot[],
    teamLabel = 'Équipe',
  }: {
    trainers?: EliteFourTrainerPreviewSnapshot[];
    teamLabel?: string;
  } = $props();

  let selectedTrainerIndex = $state(0);

  const selectedTrainer = $derived(trainers[selectedTrainerIndex] ?? null);

  $effect(() => {
    if (selectedTrainerIndex >= trainers.length) {
      selectedTrainerIndex = Math.max(0, trainers.length - 1);
    }
  });

  function selectTrainer(index: number) {
    selectedTrainerIndex = index;
  }
</script>

{#if trainers.length > 0}
  <div class="elite-four-trainer-dex">
    <div
      class="elite-four-trainer-dex__strip"
      role="tablist"
      aria-label={teamLabel}
    >
      {#each trainers as trainer, idx (trainer.championName)}
        <button
          type="button"
          role="tab"
          class="elite-four-trainer-chip elite-four-trainer-dex__chip"
          class:active={selectedTrainerIndex === idx}
          aria-selected={selectedTrainerIndex === idx}
          onclick={() => selectTrainer(idx)}
        >
          {#if trainer.spriteUrl}
            <img
              src={trainer.spriteUrl}
              alt=""
              class="elite-four-trainer-sprite"
              onerror={(e) => { (e.currentTarget as HTMLImageElement).style.display = 'none'; }}
            />
          {:else}
            <span class="elite-four-trainer-avatar-fallback" style="display:inline-flex;">
              {trainer.championName.charAt(0)}
            </span>
          {/if}
          <span class="elite-four-trainer-dex__chip-text">
            <span class="elite-four-trainer-name">{trainer.championName}</span>
            <span class="elite-four-trainer-role">{trainer.roleLabel}</span>
          </span>
        </button>
      {/each}
    </div>

    {#if selectedTrainer}
      <div class="elite-four-trainer-dex__panel" role="tabpanel">
        <div class="elite-four-trainer-dex__panel-header">
          {#if selectedTrainer.spriteUrl}
            <img src={selectedTrainer.spriteUrl} alt="" class="elite-four-trainer-dex__panel-sprite" />
          {/if}
          <div>
            <strong>{selectedTrainer.championName}</strong>
            <div>
              <span class="type-badge type-{selectedTrainer.specialtyType}">
                {selectedTrainer.specialtyType}
              </span>
            </div>
          </div>
        </div>

        <h5 class="elite-four-trainer-dex__team-label">{teamLabel}</h5>
        <div class="elite-four-trainer-dex__team-grid">
          {#each selectedTrainer.team as mon, pIdx (pIdx)}
            <div class="elite-four-trainer-dex__mon" title={mon.displayName}>
              <img
                src={mon.spriteUrl}
                alt={mon.displayName}
                class="elite-four-trainer-dex__mon-sprite"
                loading="lazy"
              />
              <span class="elite-four-trainer-dex__mon-name">{mon.displayName}</span>
              <span class="elite-four-trainer-dex__mon-level">Lv.{mon.level}</span>
            </div>
          {/each}
        </div>
      </div>
    {/if}
  </div>
{/if}
