<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- badges grid from arenaSnapshot */
  import { arena } from '../../stores/arena.svelte.ts';
  import { game } from '../../../gameManager.js';
  import { bindArenaBadgeTooltips } from '../../lib/arenaSnapshot.js';

  let snap = $derived(arena.snapshot);
  let listEl: HTMLDivElement | undefined = $state();

  $effect(() => {
    const html = snap.badgesHtml;
    const el = listEl;
    const gm = game;
    if (!el || !gm) return;
    bindArenaBadgeTooltips(el, gm);
  });
</script>

<div class="account-talents-box trainer-card-box">
  <h4 id="arenasTalentsTitleLabel">{snap.trainerCardTitle}</h4>
  <div bind:this={listEl} id="badgesList" class="trainer-badges-grid">
    <!-- svelte-ignore a11y_no_static_element_interactions -->
    {@html snap.badgesHtml}
  </div>
</div>
